"""
db_service.py - Dienst fuer Datenbankoperationen.
"""

import logging
import re
from typing import Any, cast

import mariadb
import pandas as pd

from ..constants import DATABASE
from .client import DbCredentials, connect_to_db

logger = logging.getLogger(__name__)

SqlParams = tuple[Any, ...] | list[Any]


def get_query_text(
    query_name: str,
    database: str = DATABASE,
    db_credentials: DbCredentials | None = None,
) -> str:
    """Laedt den Text einer gespeicherten SQL-Abfrage aus der Datenbank.

    Args:
        query_name: Der Name der Abfrage.
        database: Der Name der Datenbank, aus der die Abfrage geladen werden soll.
        db_credentials: Optionale direkte DB-Zugangsdaten.

    Returns:
        Der SQL-Text der Abfrage.

    Raises:
        ValueError: Wenn die Abfrage nicht gefunden wurde.
        mariadb.Error: Bei Datenbankfehlern.
    """
    connection = connect_to_db(database, credentials=db_credentials)
    try:
        cursor = connection.cursor()
        cursor.execute("SELECT querytext FROM tb_stored_queries WHERE queryname = %s", (query_name,))
        result = cursor.fetchone()
        if not result:
            raise ValueError(f"SQL-Abfrage '{query_name}' nicht in tb_stored_queries gefunden")
        query_text = result[0]
        if not isinstance(query_text, str):
            raise ValueError(f"SQL-Abfrage '{query_name}' enthaelt keinen Text")
        return query_text
    except mariadb.Error as exc:
        logger.error("Fehler beim Laden der SQL-Abfrage %s: %s", query_name, exc, exc_info=True)
        raise
    finally:
        connection.close()


def execute_sql_query(
    query: str,
    params: SqlParams | None = None,
    executemany: bool = False,
    database: str = DATABASE,
    db_credentials: DbCredentials | None = None,
) -> pd.DataFrame | bool:
    """Fuehrt eine SQL-Abfrage aus und gibt die Ergebnisse zurueck.

    Fuer SELECT- oder CALL-Abfragen wird ein DataFrame zurueckgegeben.
    Fuer andere Abfragen (INSERT, UPDATE, DELETE) wird True bei Erfolg zurueckgegeben.
    """
    connection = connect_to_db(database, credentials=db_credentials)
    try:
        cursor = connection.cursor(dictionary=True)
        if executemany and params:
            cursor.executemany(query, params)
        elif params:
            cursor.execute(query, params)
        else:
            cursor.execute(query)

        query_type = query.strip().upper()
        if query_type.startswith(("SELECT", "CALL", "WITH", "SHOW", "DESCRIBE", "DESC", "EXPLAIN")):
            return pd.DataFrame(cursor.fetchall())

        connection.commit()
        return True
    except mariadb.Error as exc:
        logger.error("Fehler beim Ausfuehren der Abfrage: %s", exc, exc_info=True)
        raise
    finally:
        connection.close()


def execute_dataframe_query(
    query: str,
    params: SqlParams | None = None,
    database: str = DATABASE,
    db_credentials: DbCredentials | None = None,
) -> pd.DataFrame:
    """Fuehrt eine SQL-Abfrage aus und erwartet ein DataFrame-Ergebnis.

    Diese Funktion ist fuer SELECT-, CALL- und report-Abfragen gedacht.
    Schreibende Abfragen sollen weiter `execute_sql_query` oder spezifische
    Funktionen nutzen.
    """
    result = execute_sql_query(
        query,
        params=params,
        database=database,
        db_credentials=db_credentials,
    )
    if isinstance(result, bool):
        raise RuntimeError("SELECT-Abfrage hat kein DataFrame-Ergebnis geliefert")
    return result


def update_last_updated(
    report: str,
    date: str,
    database: str = DATABASE,
    db_credentials: DbCredentials | None = None,
) -> bool:
    """Aktualisiert die Spalte Last_Import in der tabelle tb_bewegungsdaten."""
    connection = connect_to_db(database, credentials=db_credentials)
    try:
        cursor = connection.cursor()

        sql_query = """
            INSERT INTO tb_bewegungsdaten (report, Last_Import)
            VALUES (?, ?)
            ON DUPLICATE KEY UPDATE
                report = VALUES(report),
                Last_Import = VALUES(Last_Import)
        """

        cursor.execute(sql_query, (report, date))
        connection.commit()
        logger.info("Last_Import erfolgreich aktualisiert mit Datum: %s", date)
        return True
    except mariadb.Error as exc:
        logger.error("Fehler beim Einfuegen/Aktualisieren: %s", exc, exc_info=True)
        raise
    finally:
        connection.close()


def status_table(
    target_table: str,
    status: str,
    database: str = DATABASE,
    db_credentials: DbCredentials | None = None,
) -> Any:
    """Holt den MIN- oder MAX-Wert der Spalte 'lastupdated' aus einer tabelle."""
    connection = connect_to_db(database, credentials=db_credentials)
    cursor = None
    try:
        cursor = connection.cursor(dictionary=True)
        if status not in ("MAX", "MIN"):
            raise ValueError(f"Ungueltiger status: {status}. Erlaubt sind 'MAX' und 'MIN'.")

        if not re.match(r"^[a-zA-Z0-9_]+$", target_table):
            raise ValueError(f"Ungueltiger Tabellenname: {target_table}")

        cursor.execute(f"SELECT {status}(lastupdated) AS val FROM {target_table}")
        result = cursor.fetchone()
        if result:
            return cast(dict[str, Any], result)["val"]
        return "Keine Daten gefunden"
    except mariadb.Error as exc:
        logger.error("Ein Fehler ist aufgetreten: %s", exc, exc_info=True)
        raise
    finally:
        if cursor:
            cursor.close()
        connection.close()


def prozedur_db(
    prozedur: str,
    database: str = DATABASE,
    db_credentials: DbCredentials | None = None,
) -> bool:
    """Fuehrt eine gespeicherte prozedur in der angegebenen Datenbank aus."""
    logger.info("Starte Ausfuehrung der prozedur: %s in Datenbank: %s", prozedur, database)
    connection = connect_to_db(database, credentials=db_credentials)
    try:
        with connection.cursor() as cursor:
            cursor.callproc(prozedur)
            connection.commit()
            logger.info("Stored Procedure '%s' erfolgreich ausgefuehrt.", prozedur)
            return True
    except mariadb.Error as exc:
        logger.error("Fehler bei der Ausfuehrung der Stored Procedure oder der Datenabfrage: %s", exc, exc_info=True)
        raise
    finally:
        connection.close()
        logger.info("Verbindung zur Datenbank geschlossen.")
